source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    patterns = []
    for r in {0, h - 1}:
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] != 0:
                c += 1
            if c - start > 1:
                patterns.append(grid[r][start:c])
    color_pattern = {}
    for seq in patterns:
        for color in seq:
            color_pattern.setdefault(color, seq)
    pattern_cells = {(r, c) for r in {0, h - 1} for c, v in enumerate(grid[r]) if v != 0}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in pattern_cells:
                continue
            seq = color_pattern.get(color)
            if seq is None:
                continue
            i = seq.index(color)
            for j, value in enumerate(seq):
                x = c + j - i
                if 0 <= x < w:
                    out[r][x] = value
    return out
'''
